    "title": "애플샤인농원 현장학습",
    "content": "애플샤인농원에서 향긋한 쑥을 캐고 개구리도 관찰하며 봄의 자연을 만끽했습니다. \n직접 캔 쑥으로 떡 모양틀  공룡 쑥비누 만들기 활동을 하며 즐거운 체험도 해보았답니다. 에어바운스에서 마음껏 뛰어놀며 활기차고 행복한 추억을 쌓았습니다.",
